const text = (msg.status && msg.status.text) ? String(msg.status.text).toLowerCase() : '';
global.set('mqttConnected', text.includes('connected') && !text.includes('disconnected'));
return null;

const STATE_LABELS = [
    'NORMAL',
    'WARNING (MINOR CHEMICAL LEAK)',
    'CRITICAL (SEVERE TOXIC LEAK)',
    'EMERGENCY (CONFIRMED FIRE)',
    'SENSOR GLITCH / FALSE ALARM'
];

let raw = msg.payload;
if (typeof raw === 'string') {
    try {
        raw = JSON.parse(raw);
    } catch (e) {
        node.warn('Dropped malformed JSON telemetry on topic ' + msg.topic);
        return [null, null, null];
    }
}
if (!raw || typeof raw !== 'object') {
    return [null, null, null];
}

const topicNode = (msg.topic || 'lab_main_s3/telemetry').split('/')[0];
const nodeId = String(raw.node || topicNode || 'lab_main_s3').replace(/[^a-zA-Z0-9_-]/g, '');
const state = Number.isFinite(Number(raw.state)) ? Math.max(0, Math.min(4, parseInt(raw.state, 10))) : 0;
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();

const telemetry = {
    node: nodeId,
    state: state,
    state_label: STATE_LABELS[state] || 'UNKNOWN',
    temp: Number(raw.temp ?? 0),
    humidity: Number(raw.humidity ?? 0),
    pressure: Number(raw.pressure ?? 0),
    tvoc: parseInt(raw.tvoc ?? 0, 10) || 0,
    eco2: parseInt(raw.eco2 ?? 0, 10) || 0,
    flame: (raw.flame === true || Number(raw.flame) === 1) ? 1 : 0,
    presence: Boolean(raw.presence),
    distance_cm: parseInt(raw.distance_cm ?? 0, 10) || 0,
    uptime_s: parseInt(raw.uptime_s ?? 0, 10) || 0,
    received_at: nowIso
};

// Track previous state & DB throttle per node
const lastStateByNode = global.get('lastStateByNode') || {};
const lastDbWriteByNode = global.get('lastDbWriteByNode') || {};
const latestByNode = global.get('latestByNode') || {};

const prevState = (nodeId in lastStateByNode) ? lastStateByNode[nodeId] : null;
const stateChanged = (prevState !== null && prevState !== state);
const firstAlertOnBoot = (prevState === null && state > 0);

lastStateByNode[nodeId] = state;
latestByNode[nodeId] = telemetry;
global.set('lastStateByNode', lastStateByNode);
global.set('latestByNode', latestByNode);
global.set('latestTelemetry', telemetry);
global.set('lastTelemetryAt', nowIso);

// Output 1: Always push live 1Hz telemetry to WebSocket clients
const wsMsg = {
    payload: JSON.stringify(telemetry)
};

// Output 2: Smart InfluxDB v2 rate gate (max 1 write / 10s, but NEVER skip state transitions)
let dbMsg = null;
const lastWrite = lastDbWriteByNode[nodeId] || 0;
const DB_MIN_INTERVAL_MS = 10000;
if (stateChanged || firstAlertOnBoot || (nowMs - lastWrite >= DB_MIN_INTERVAL_MS)) {
    lastDbWriteByNode[nodeId] = nowMs;
    global.set('lastDbWriteByNode', lastDbWriteByNode);
    dbMsg = {
        payload: [
            {
                state: telemetry.state,
                temp: telemetry.temp,
                humidity: telemetry.humidity,
                pressure: telemetry.pressure,
                tvoc: telemetry.tvoc,
                eco2: telemetry.eco2,
                flame: telemetry.flame,
                presence: telemetry.presence,
                distance_cm: telemetry.distance_cm,
                uptime_s: telemetry.uptime_s
            },
            {
                node: telemetry.node
            }
        ]
    };
}

// Output 3: Edge-triggered Alerts (Telegram + FCM) — fire ONLY on state transition or non-zero boot
let alertMsg = null;
if (firstAlertOnBoot || (stateChanged && (state > 0 || prevState > 0))) {
    alertMsg = {
        payload: telemetry,
        prevState: prevState,
        isRecovery: (state === 0 && prevState > 0)
    };
}

return [wsMsg, dbMsg, alertMsg];

const token = (env.get('TELEGRAM_BOT_TOKEN') || '').trim();
const chatId = (env.get('TELEGRAM_CHAT_ID') || '').trim();

if (!token || !chatId) {
    node.status({ fill: 'grey', shape: 'ring', text: 'Telegram not configured' });
    return null;
}

const d = msg.payload;
const icons = { 0: '✅', 1: '⚠️', 2: '☣️', 3: '🔥', 4: '🛠️' };
const header = msg.isRecovery
    ? '✅ <b>LAB SAFETY RESOLVED — BACK TO NORMAL</b>'
    : `${icons[d.state] || '🚨'} <b>LAB SAFETY ALERT: ${d.state_label}</b>`;

const localTime = new Date(d.received_at).toLocaleString('en-MY', {
    timeZone: 'Asia/Kuala_Lumpur',
    hour12: false
});

const lines = [
    header,
    ``,
    `<b>Node:</b> <code>${d.node}</code>`,
    `<b>State:</b> ${d.state} (${d.state_label})`,
    `<b>Temperature:</b> ${d.temp.toFixed(1)} °C`,
    `<b>Humidity:</b> ${d.humidity.toFixed(1)} %`,
    `<b>TVOC / eCO2:</b> ${d.tvoc} ppb / ${d.eco2} ppm`,
    `<b>Flame Sensor:</b> ${d.flame ? 'DETECTED' : 'Clear'}`,
    `<b>Human Presence:</b> ${d.presence ? 'Detected (' + d.distance_cm + ' cm)' : 'None'}`,
    `<b>Time (MYT):</b> ${localTime}`
];

msg.method = 'POST';
msg.url = `https://api.telegram.org/bot${token}/sendMessage`;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    chat_id: chatId,
    text: lines.join('\n'),
    parse_mode: 'HTML'
};

node.status({ fill: d.state >= 2 ? 'red' : (d.state === 0 ? 'green' : 'yellow'), shape: 'dot', text: `Sent state ${d.state}` });
return msg;

const fcmHelper = global.get('fcmHelper');
if (!fcmHelper || !fcmHelper.isReady()) {
    node.status({ fill: 'grey', shape: 'ring', text: 'FCM not configured' });
    return null;
}

const d = msg.payload;
const title = msg.isRecovery
    ? 'Lab Safety: All Clear (Normal)'
    : `Lab Safety Alert: ${d.state_label}`;

const body = msg.isRecovery
    ? `${d.node} returned to normal. Temp ${d.temp.toFixed(1)}°C, TVOC ${d.tvoc} ppb.`
    : `${d.node} — Temp: ${d.temp.toFixed(1)}°C | TVOC: ${d.tvoc} ppb | Flame: ${d.flame ? 'YES' : 'No'} | Presence: ${d.presence ? 'Yes' : 'No'}`;

fcmHelper.sendAlert({
    title,
    body,
    data: {
        node: d.node,
        state: d.state,
        state_label: d.state_label,
        temp: d.temp,
        tvoc: d.tvoc,
        flame: d.flame,
        presence: d.presence,
        received_at: d.received_at
    }
}).then((res) => {
    node.status({ fill: 'green', shape: 'dot', text: `FCM sent (${res.topic})` });
    node.send({ topic: 'fcm/result', payload: res });
    node.done();
}).catch((err) => {
    node.status({ fill: 'red', shape: 'ring', text: 'FCM error' });
    node.error('FCM push failed: ' + err.message, msg);
    node.done();
});

return null;

const fcmHelper = global.get('fcmHelper');
const latestByNode = global.get('latestByNode') || {};

msg.statusCode = 200;
msg.payload = {
    status: 'ok',
    service: 'lab-safety-backend',
    timestamp: new Date().toISOString(),
    mqttConnected: Boolean(global.get('mqttConnected')),
    fcm: fcmHelper ? fcmHelper.getStatus() : { ready: false },
    telegramConfigured: Boolean((env.get('TELEGRAM_BOT_TOKEN') || '').trim() && (env.get('TELEGRAM_CHAT_ID') || '').trim()),
    lastTelemetryAt: global.get('lastTelemetryAt') || null,
    nodes: Object.keys(latestByNode)
};
return msg;

const requestedNode = (msg.req && msg.req.query && msg.req.query.node) ? String(msg.req.query.node) : '';
const latestByNode = global.get('latestByNode') || {};
const latest = requestedNode ? latestByNode[requestedNode] : global.get('latestTelemetry');

msg.statusCode = 200;
if (!latest) {
    msg.payload = {
        ok: true,
        hasData: false,
        data: null,
        message: 'Waiting for first telemetry packet from ESP32.'
    };
} else {
    msg.payload = {
        ok: true,
        hasData: true,
        data: latest
    };
}
return msg;

const RANGE_MAP = {
    '15m': { start: '-15m', window: '10s' },
    '1h':  { start: '-1h',  window: '30s' },
    '6h':  { start: '-6h',  window: '2m'  },
    '24h': { start: '-24h', window: '5m'  },
    '7d':  { start: '-7d',  window: '30m' },
    '30d': { start: '-30d', window: '2h'  }
};

const reqRange = (msg.req && msg.req.query && msg.req.query.range) ? String(msg.req.query.range) : '1h';
const cfg = RANGE_MAP[reqRange] || RANGE_MAP['1h'];
const appliedRange = RANGE_MAP[reqRange] ? reqRange : '1h';

const rawNode = (msg.req && msg.req.query && msg.req.query.node) ? String(msg.req.query.node) : '';
const safeNode = rawNode.replace(/[^a-zA-Z0-9_-]/g, '');
const bucket = env.get('INFLUXDB_BUCKET') || 'lab_safety';

const nodeFilter = safeNode ? `|> filter(fn: (r) => r.node == "${safeNode}")` : '';

msg._historyMeta = { range: appliedRange, window: cfg.window, node: safeNode || 'all' };
msg.query = `
from(bucket: "${bucket}")
  |> range(start: ${cfg.start})
  |> filter(fn: (r) => r._measurement == "lab_telemetry")
  ${nodeFilter}
  |> filter(fn: (r) => r._field == "temp" or r._field == "humidity" or r._field == "pressure" or r._field == "tvoc" or r._field == "eco2" or r._field == "state" or r._field == "flame" or r._field == "distance_cm")
  |> aggregateWindow(every: ${cfg.window}, fn: mean, createEmpty: false)
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> sort(columns: ["_time"])
`;
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const cleaned = rows.map((r) => ({
    time: r._time,
    node: r.node,
    temp: r.temp !== undefined ? Number(Number(r.temp).toFixed(2)) : null,
    humidity: r.humidity !== undefined ? Number(Number(r.humidity).toFixed(2)) : null,
    pressure: r.pressure !== undefined ? Number(Number(r.pressure).toFixed(2)) : null,
    tvoc: r.tvoc !== undefined ? Math.round(Number(r.tvoc)) : null,
    eco2: r.eco2 !== undefined ? Math.round(Number(r.eco2)) : null,
    state: r.state !== undefined ? Math.round(Number(r.state)) : null,
    flame: r.flame !== undefined ? Math.round(Number(r.flame)) : null,
    distance_cm: r.distance_cm !== undefined ? Math.round(Number(r.distance_cm)) : null
}));

const meta = msg._historyMeta || {};
msg.statusCode = 200;
msg.payload = {
    ok: true,
    range: meta.range || '1h',
    window: meta.window || '30s',
    node: meta.node || 'all',
    count: cleaned.length,
    data: cleaned
};
return msg;

const VALID_RANGES = ['1h', '6h', '24h', '7d', '30d'];
const reqRange = (msg.req && msg.req.query && msg.req.query.range) ? String(msg.req.query.range) : '7d';
const range = VALID_RANGES.includes(reqRange) ? reqRange : '7d';

const reqLimit = parseInt((msg.req && msg.req.query && msg.req.query.limit) || '50', 10);
const limit = Number.isFinite(reqLimit) ? Math.max(1, Math.min(200, reqLimit)) : 50;
const bucket = env.get('INFLUXDB_BUCKET') || 'lab_safety';

msg._alertsMeta = { range, limit };
msg.query = `
from(bucket: "${bucket}")
  |> range(start: -${range})
  |> filter(fn: (r) => r._measurement == "lab_telemetry")
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r.state and r.state > 0)
  |> sort(columns: ["_time"], desc: true)
  |> limit(n: ${limit})
`;
return msg;

const STATE_LABELS = [
    'NORMAL',
    'WARNING (MINOR CHEMICAL LEAK)',
    'CRITICAL (SEVERE TOXIC LEAK)',
    'EMERGENCY (CONFIRMED FIRE)',
    'SENSOR GLITCH / FALSE ALARM'
];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const alerts = rows.map((r) => ({
    time: r._time,
    node: r.node,
    state: Number(r.state),
    state_label: STATE_LABELS[Number(r.state)] || 'UNKNOWN',
    temp: r.temp !== undefined ? Number(Number(r.temp).toFixed(1)) : null,
    humidity: r.humidity !== undefined ? Number(Number(r.humidity).toFixed(1)) : null,
    tvoc: r.tvoc !== undefined ? Math.round(Number(r.tvoc)) : null,
    eco2: r.eco2 !== undefined ? Math.round(Number(r.eco2)) : null,
    flame: r.flame !== undefined ? Number(r.flame) : 0,
    presence: Boolean(r.presence),
    distance_cm: r.distance_cm !== undefined ? Math.round(Number(r.distance_cm)) : null
}));

const meta = msg._alertsMeta || {};
msg.statusCode = 200;
msg.payload = {
    ok: true,
    range: meta.range || '7d',
    count: alerts.length,
    alerts
};
return msg;

const token = (msg.payload && typeof msg.payload.token === 'string') ? msg.payload.token.trim() : '';
if (!token) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Missing required JSON field: token' };
    return msg;
}

const fcmHelper = global.get('fcmHelper');
if (!fcmHelper || !fcmHelper.isReady()) {
    msg.statusCode = 503;
    msg.payload = { ok: false, error: 'FCM is not configured on backend yet (missing service account JSON).' };
    return msg;
}

fcmHelper.subscribeToken(token).then((res) => {
    msg.statusCode = res.ok ? 200 : 500;
    msg.payload = res;
    node.send(msg);
    node.done();
}).catch((err) => {
    msg.statusCode = 500;
    msg.payload = { ok: false, error: err.message };
    node.send(msg);
    node.done();
});

return null;

const token = (msg.payload && typeof msg.payload.token === 'string') ? msg.payload.token.trim() : '';
if (!token) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'Missing required JSON field: token' };
    return msg;
}

const fcmHelper = global.get('fcmHelper');
if (!fcmHelper || !fcmHelper.isReady()) {
    msg.statusCode = 503;
    msg.payload = { ok: false, error: 'FCM is not configured on backend yet.' };
    return msg;
}

fcmHelper.unsubscribeToken(token).then((res) => {
    msg.statusCode = res.ok ? 200 : 500;
    msg.payload = res;
    node.send(msg);
    node.done();
}).catch((err) => {
    msg.statusCode = 500;
    msg.payload = { ok: false, error: err.message };
    node.send(msg);
    node.done();
});

return null;

const expectedKey = (env.get('API_ADMIN_KEY') || '').trim();
if (!expectedKey) {
    msg.statusCode = 503;
    msg.payload = { ok: false, error: 'API_ADMIN_KEY is not configured on backend.' };
    return [msg, null];
}

const providedKey = (msg.req && msg.req.headers && msg.req.headers['x-api-key']) ? String(msg.req.headers['x-api-key']).trim() : '';
if (providedKey !== expectedKey) {
    msg.statusCode = 401;
    msg.payload = { ok: false, error: 'Unauthorized: invalid X-API-Key header.' };
    return [msg, null];
}

const latest = global.get('latestTelemetry');
if (latest && Number(latest.state) !== 0) {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: 'OTA blocked by safety interlock: lab is not in STATE_NORMAL.', currentState: latest.state };
    return [msg, null];
}

const mqttMsg = {
    topic: 'esp32/ota_trigger',
    payload: 'trigger'
};

msg.statusCode = 200;
msg.payload = { ok: true, topic: 'esp32/ota_trigger', message: 'OTA trigger published to ESP32.' };
return [msg, mqttMsg];

if (!msg.res) {
    return null;
}
msg.statusCode = 500;
msg.payload = {
    ok: false,
    error: (msg.error && msg.error.message) ? msg.error.message : 'Internal backend error'
};
return msg;
